#!/bin/sh
# Generated by installgen (https://github.com/lovrozagar/installgen). Regenerate it with `installgen build`.
#
#   curl -fsSL <url> | sh
#   curl -fsSL <url> | sh -s -- 1.2.3
set -u

main() {
	name=@@NAME@@
	base_url=@@BASE_URL@@
	latest_url=@@LATEST_URL@@
	default_version=@@DEFAULT_VERSION@@
	tag_prefix=@@TAG_PREFIX@@
	install_dir="${@@ENV_PREFIX@@_INSTALL_DIR:-}"
	[ -n "$install_dir" ] || install_dir=@@INSTALL_DIR@@
	install_dir_display=@@INSTALL_DIR_DISPLAY@@
	modify_path=@@MODIFY_PATH@@
	[ -z "${@@ENV_PREFIX@@_NO_MODIFY_PATH:-}" ] || modify_path=0
	requested="${1:-${@@ENV_PREFIX@@_VERSION:-}}"
	message=@@MESSAGE@@
	sh_url=@@SH_URL@@
	ps1_url=@@PS1_URL@@

	fetch_curl() { curl -fsSL @@CURL_FLAGS@@ "$1"; }
	fetch_wget() { wget -q @@WGET_FLAGS@@ -O - "$1"; }
	supported() {
		case " @@PLATFORMS@@ " in
		*" $1 "*) return 0 ;;
		esac
		return 1
	}
	resolve_platform() {
		case "$1" in
@@PLATFORM_CASES@@
		*) return 1 ;;
		esac
	}

	printf '%s\n' "$name $base_url $latest_url $default_version $tag_prefix $install_dir $install_dir_display"
	printf '%s\n' "$modify_path $requested $message $sh_url $ps1_url"
}

main "$@"
